INSERT INTO COMMUNITY_IMG_TBL ( IMG_NO, IMG_PATH, IMG_RENAME, IMG_ORIGINAL_NAME, IMG_MAIN, COMMUNITY_NO ) SELECT SEQ_IMG_NO.NEXTVAL, A.* FROM (
SELECT #{img.imgPath} as IMG_PATH, #{img.imgRename} as IMG_RENAME, #{img.imgOriginalName} as IMG_ORIGINAL_NAME, 'N' as IMG_MAIN , #{img.communityNo} as COMMUNITY_NO FROM DUAL
) A
